string intToRoman(int num) {
    int vals[] = {1000,900,500,400,100,90,50,40,10,9,5,4,1};
    string syms[] = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
    string ans;
    for (int i = 0; i < 13; i++) {
        while (num >= vals[i]) {
            ans += syms[i];
            num -= vals[i];
        }
    }
    return ans;
}
// 贪心：从大到小 | 映射表降序 | 13对映射覆盖所有情况
